    audio_url: '/audio/akem-seni-men-suiemin.mp3',
    storage_path: null,
    duration_seconds: 302,
    lyrics:
      'Әкем, Сені мен сүйемін,\nЖүрегімнің қалауы да,\nСен керексің.\n\nИса, сүйікті Құтқарушым,\nБәрі үшін Саған қарыздармын,\nСаған бәрін берем.\n\nМадақтайды періштелер,\nБіз балаңбыз табынамыз.\n\nӘлемімсің, Құдайымсың,\nӨмірімді Саған арнайм.\nТәңірімсің, Сені сүйем,\nСенен ешкім айыра алмайды.\n\nМенде бардың бәрін берем,\nПатшам, Сен үшін өмір сүрем,\nТек Сен үшін.\n\nӘрбір күнім Сенің сыйың,\nСенің еркіңмен өткіземін мен,\nТек Сен үшін.',
