      'Алыс шамын түкке тұрмас,\nЖансың деген ойлармен.\nЛайықсыз деп ішкі дауысың,\nЖадады сабырмен.\n\nСансыз күдік торлап менің,\nТұмшалайды санамды.\nАрашалап алшы мені,\nЖойшы жаман ойларды.\n\nСүйемін дейсің, егер қорықсам,\nСенім арт дейсің, егер қорықсам.\nКөтерем дейсің, кенет сүрінсем,\nБіргемін дейсің, жалғыз сезінсем.\nСенемін, сенемін,\nСөзіңе сенемін.\n\nҚымбатпын мен көз алдыңда,\nАлтыннан да бағалы.\nТек Өзіңмен жолығамын,\nЖүрек тыным табады.\n\nАқтарып мен бар сырымды,\nЖығыламын алдыңда.\nЖеңісің де, жеңілісің де,\nТек Өзіңнің қолыңда.',
