    audio_url: '/audio/ieshua.mp3',
    storage_path: null,
    duration_seconds: 599,
    lyrics:
      'Иисус, мы ждём Тебя,\nПриди, Возлюбленный!\nПриди во всей Своей силе и славе,\nГосподь, мы ждём Тебя!\n\nМой Возлюбленный — всех прекраснее,\nСреди тысяч и тысяч!\nМой Возлюбленный — всех прекраснее,\nСреди тысяч и тысяч!\n\nИешуа! А-а-а...\nИешуа! А-а-а...\n\nО, Иешуа, Возлюбленный моей души,\nЦерковь ждёт Тебя — приди!\nВо всей Твоей славе,\nВо всей Твоей силе,\nВо всей полноте — приди!\nМы ожидаем этой встречи,\nИисус, Жених моей души!\n\nДа будет здесь Твоё Царство,\nЗдесь Твоя сила,\nЗдесь Твоя слава вовеки! Аминь!',
