    audio_url: '/audio/zhuregimdi-ozgertshi-mahabbat.mp3',
    storage_path: null,
    duration_seconds: 197,
    lyrics:
      'Жүрегімді өзгертші, Тәңір,\nСені ғана аңсап тұрайын.\nЖүрегімді өзгертші, Тәңір,\nСаған ғана мойын бұрайын.\n\nСенің атың — ыстық махаббат,\nСенің атың — рақым шапағат.\nСұраймын мен Сенен, бер маған\nДаналық, қанағат!\n\nӨмірімді өзгертші, Тәңір,\nРухыңмен мен Сенің толайын.\nӨмірімді өзгертші, Тәңір,\nӘлемге мен жарық болайын.\n\nСенің атың — ыстық махаббат,\nСенің атың — рақым шапағат.\nСұраймын мен Сенен, бер маған\nДаналық, қанағат!',
