    storage_path: null,
    duration_seconds: 316,
    lyrics:
      'Киелі Рух,\nСенің қасыңда\nМәңгі болғым келеді,\nҚұшағыңа алшы.\n\nКиелі Рух,\nНәзік жазыңды\nЖүрегіммен сезіп,\nТолтыршы.\n\nКиелі Рух, Киелі Рух,\nКиелі Рух, Киелі Рух!\n\nӨз өмірімді\nСаған бағыштап,\nБір тұтас болғым келеді\nСенімен, Ием!\n\nРизамын Саған,\nЖетеле мені,\nСаған теңдес ешкім жоқ,\nСүйемін Сені!\n\nШын жүректен\nРахметімді\nСаған ғана айтамын!\nСұраймын Сенен,\nЖетелеші,\nӘкемнің тағына!',
