    storage_path: null,
    duration_seconds: 342,
    lyrics:
      'Возьми меня, как глину,\nИ возьми меня, как стрелу.\nСлепи из меня всё, что хочешь,\nЗапусти меня в цель Свою.\n\nЯви Свою славу,\nЯви Свою силу, Иисус!\nЯви Свою славу,\nЯви Свою силу, Иисус!\n\nЯ верю в чудеса,\nВерю в Божие слова,\nВерю в Божию любовь,\nЧерез кровь, святую кровь!\nИ всё изменится вокруг,\nПотому что Бог — мой Друг,\nПотому что Он со мной,\nОн — мой Герой, Иисус — Герой!',
