    storage_path: null,
    duration_seconds: 380,
    lyrics:
      'Воду в вино превратил,\nСлепые глаза Ты открыл.\nНет таких, Бог,\nНет, как Ты!\n\nТы нас из праха поднял,\nСвет Твой во тьме воссиял.\nНет таких, Бог,\nНет, как Ты!\n\nНаш Бог великий,\nОн Всемогущий,\nБог, Ты превыше всего, что дышит!\nНаш Бог — Целитель,\nВсё в Его силе,\nНаш Бог, наш Бог!\n\nИ если Бог с нами,\nКто против нас восстанет?\nИ если Бог с нами,\nКто может против быть?',
