    storage_path: null,
    duration_seconds: 177,
    lyrics:
      'Құдай — өмірімнің қайнар көзі,\nТағдырымның басқарушысы.\nЕң даусың сүйікті екен,\nҚабылдашы мені!\nЕшқашан мені тастамайды,\nДұшпаныммен құтқарды!\nӨмірімдегі жарық —\nҚұдайсың Сен!\n\nҚұдай — менің Патшам,\nҚұдай — менің жұлдызым!\nҚұдай — менің бар атым,\nҚұдай — менің жүрегім, о!\n\nҚұдай күшті, Құдай мықты,\nТәңірім киелі, Саған табынам!\nҚұдай күшті, Құдай мықты,\nТәңірім киелі, Саған табынам!',
