    lyrics:
      "Барлық күштерден биіксің,\nЖаратылыстардан, табиғаттардан.\nЖоғары бүкіл ақылдан, даналықтан.\nПатшалардың Патшасы Сен!\n\nАтақтан, даңқтардан Ол жоғары,\nЖоғары ғажаптардан адамзат көрген.\nЖер бетіндегі зор байлықтан жоғары,\nТеңдесі жоқ мейірім берген!\n\nАяусыз айқышқа таңдырды,\nӘкесі бас тартып қалдырды.\nРаушандай жерге тапталған,\nБар күнәмнан ақтаған,\nОл Жоғары!",
