    lyrics:
      "Би толтырсын үйімізді,\nШаттық кернеп даланы.\nИса алдында бәрі құлап\nТәубеге кеп сиынсын.\n\nАсқар таудан аңғарларға\nСаған мадақ қалықтасын.\nЗаңғар көктен халықтарға\nҒажайып ән құйылсын!\n\nБіз соңыңнан ерген кезде,\nНұрың түрсін түнекті.\nДаңқың толтырсын ғаламды,\nТасқынындай тірі судың.\n\nАллелуя! Аллелуя!\nАллелуя! Аллелуя!",
