    storage_path: null,
    duration_seconds: 349,
    lyrics:
      "Бүкіл атақ мәртебемді беремін,\nБар еңбегім, даңқымды алдыңа қоямын!\nКөрмеп еді әлем Сендей ешкімді,\nСен ғана, лайықсың, жалғыз Сен лайықсың!\n\nҚұрметтегенг(е) атыңды Сен жақынсың,\nМәңгі жомарт, сүюші де сол - Сен Өзіңсің,\nӨмірімді бір Өзіңмен толтырдың,\nБарлық мадақ тек Саған! Барлық мадақ тек - Саған!\n\nСен лайықсың, о, Ием, ұлы даңққа!\nСен лайықсың, барлық құрметке,\nСен үшін өмір сүрем, менде бардың бәрімен,\nТабынам Саған!\n\nТабынам Саған! Құрметтейм(ін) !\nМадақтайм(ын), Сені - Ием!",
