    storage_path: null,
    duration_seconds: 174,
    lyrics:
      "Ей адамдар жаралғандар,\nБұл дүниед-е-е-е адаспаңдар.\nИса міне, келді бізге,\nҚұтқарлыла-а-ад көз ашқандар.\n\nСол Иса Сол Иса\nОл Тәңір Ол Тәңір\nҚұтқарушым\nҚорғанышым\nҚуанышы-ы-ым\nЖұбанышым!\n\nОл сыйлады мәңгілікті,\nМойнымыздан алды жүкті.\nОл сыйлады Киелі Рухты,\nОған сенген болсын мықты.\n\nИса - Тәңір, Ол - мәңгілік,\nОл мәңгілік құрды билік.\nПатшалардың Патшасы,\nОл бәрінен тұрды биік.",
