    storage_path: null,
    duration_seconds: 194,
    lyrics:
      "Жым-жырт түн, Ғажап түн!\nМүлгіп тұр айнала.\nОяу тек, жұбайлар тебіренген,\nСүйкімді Сәбиге еміреніп,\nҚуанышқа кенелген! Қуанышқа кенелген!\n\nЖым-жырт түн, Ғажап түн!\nЖар салды көктен үн:\nҚуан, Мәсіх келді дүниеге,\nСендерге құтқарылу әкелді!\nКөктен түсті бір жарық! Көктен түсті бір жарық!\n\nЖым-жырт түн, Ғажап түн!\nТәңір сый ұсынды.\nЖан-тәнменен оны қабылдайық\nМақтасын Оны барлық халық!\nҚұтқарушы берді Ол, Құтқарушы берді Ол.",
