    duration_seconds: 33,
    lyrics:
      "Киелі, Киелі, Киелі Тәңір Ие -\nҚұдіретті Құдай.\nЕрте тұрып қуанып\nӘн саламыз Оған:\nКиелі, Киелі, Киелі Тәңір Ие -\nЖанашыр да күшті.\nҮшбірлік Құдай - мәңгі махаббат.\n\nКиелі, Киелі, Киелі Тәңір Ие -\nҚұрметпен табынып,\nКөкте киелілер даңқтап тағзым етеді.\nПеріштелер бәрі тізесін бүгеді,\nМәңгілік Иесі мейірлі, игі\n\nКиелі, Киелі, Киелі Тәңір Ие -\nТылсым құпиялы.\nКөре алмас өлілер асқақ даңқын Оның.\nОл ғана тек жалғыз, Ұлы Құдай биік\nҒажап, мықты, пәк, таза, қасиетті.\n\nКиелі, Киелі, Киелі Тәңір Ие -\nҚұдіретті Патша,\nҚұдай Атын даңқтайды\nАспан, теңіз, жерде.\nКиелі, Киелі, Киелі Тәңір Ие -\nБіз де дәріптейміз\nМәңгі Құдайды даңқ пен мадақпен.",
