    duration_seconds: 293,
    lyrics:
      "Сен киелісің,\nСен күштісің,\nСен лайықсың,\nБар мадаққа.\n\nМен еремін,\nМен тыңдаймын,\nСені сүйемін,\nӘр күнімде.\n\nӘн саламын, / Патшалар Патшасы,\nСиынамын, / Иелер Иесі,\nЛайықты / Сен күшті Құдай,\nПатшаға / Бәрінің Иесі.\nМен сүйемін, / Сен Имануил,\nҚұрметтейм, / Сен Ұлы Есім,\nБас иемін / Менің Патшамсың\nАлдында. / Сен Тоқтысың.\n\nӘн саламын, / Тірісің Құдай,\nСиынамын, / Рақымдысың Сен,\nЛайықты / Патшалығың мәңгі,\nПатшаға. / Мәңгі Бар Болушы.\nМен сүйемін, / Сен Алғашқы, Соңғысың,\nҚұрметтейм, / Басы да, Соңы.\nБас иемін / Құтқарушым Мәсіхсің,\nАлдында. / Жан Досым Өзің.\n\nТыныштық Иесі,\nСен үшін өмір сүремін.",
