      "Қазақстан жеріне, Құдайдың тірі Сөзі келді.\nАлматы аспанына, құтқарылу әкелді.\nСаған айтар әніміз, ешқашан да таусылмайды.\nДаңқыңды көтереміз, Сен оған лайықтысың !\n\nЖарылқанған жерде, тұрмыз,\nБұл Киелі, табан тіренішің!\nМадақтаймыз, бәрі естісін,\nҚұдай Патшалығы жақындады!",
    play_count: 0,
    uploaded_by: 'developer',
    status: 'published',
