    duration_seconds: 119,
    lyrics:
      "Қуан, әлем, Тәңір келмек.\nЖер, шаттан, қарсы ал.\nОл - Патшасы патшалардың,\nМадақта, сен ән сал,\nМадақта, сен ән сал,\nМадақта, мадақта, сен ән сал.\n\nҚуан, әлем, Мәсіх келді,\nҚауымдар тойлауда.\nДала, бақша, орман, төбе.\nҚуанды олар да,\nҚуанды олар да,\nҚуанды, қуанды олар да.\n\nКүнә, қасірет болмасын,\nТікенек жаппасын.\nҚарғыс оты жайлағанда,\nШапағат Ол берсін,\nШапағат Ол берсін,\nШапағат, шапағат Ол берсін.\n\nБейбіт өмірдің рахатын,\nОл Өз махаббатын,\nҰлылығын, әділдігін\nСыйлады ғой бізге,\nСыйлады ғой бізге,\nСыйлады, сыйлады ғой бізге",
