      "Қуантуды, Сені Иса мен қалаймын\nТәнімді Құдайым Сен жаңартшы.\nО, Тәңір, бас июді армандаймын,\nМахаббат нұрын көрсету үшін.\n\nБар арманым менің бұл әлемде -\nҚуаныш болу Тәңірге.\nБар арманым менің бұл әлемде -\nҚуаныш болу Тәңірге.\n\nКішіпейіл боп Сені мен шақырамын,\nЖаным мен жүрегімді тазартшы.\nҚұдайым, Саған мен жалынамын\nТағыңа Сен жол көрсетші.",
