    storage_path: null,
    duration_seconds: 370,
    lyrics:
      "Иса менің Құтқарушым\nБарлық мадақ Саған\nҚұдайымсын, данқтаймын Сені құтқарғанын ушін мені.\nЖұбанышым, Қорғанышым, тыныштық бердің маған\nЖүрегімнең шыққан әніммен сиынамын мен Саған.\n\nБарлық әлем өлен айтындар, Құдайға сиынып мадақтандар\nТаулар иіліп тағзым етсін, Оған алғыс айтындар.\nЖан тәніммен мадақтаймын Сені\nМахаббатыңмен толтырдың мені\nСаған ұқсас ешкім жоқ Құдай, Ием.",
