    lyrics:
      "Құтқарушым, Құн Төлеушім,\nКүнәдан мені азат еттің.\nҚұдіретті, киелі Құдай,\nӨмірімді Сен өзгерттің.\n\nО, Иса,\nБіздің әлемге мәңгіліктен келдің,\nҚұдайдың Тоқтысы.\nБіз үшін құрбан боп,\nҮшінші күні тірілдің.\nӘкеге жол аштың,\nБізге мәңгі өмір бердің.\nАллелуя Саған Иса",
