    duration_seconds: 97,
    lyrics:
      "Өте ертеде, заңғар көктерде\nСенің атыңды Құдай атады.\nТәңір қарады, жаратып сені.\nРизашылықпен деді Ол сонда:\n«Орасан осы ғаламда барлығын\nМен Өз қолыммен сүйіп жараттым.\nСаған қарап қуанып,\nМен шаттанамын.\nЕсте сақта:\nМен сүйем сені.\n\nСүйем сені,\nБата берем.\nСенің жүрегіңе сыйлаймын\nМахаббатымды Мен».",
