    storage_path: null,
    duration_seconds: 265,
    lyrics:
      "Бар әлемді жаратқан Құдіретті Құдай\nЖалғыз Өзің өмірімді менің өзгерттің.\nМахаббатың мен сыйыңды шексіз мәңгілік,\nКеледі енді Тәңірім мен жыр еткім.\n\nАтыңды Тәңірім мен даңқтаймын!\nБасымды Саған ғана шын иемін.\nӨмір мен сүюдің көзісің Сен,\nҚабыл ал дұғамды сиынам мен.\n\nБар әлемді жаратқан Құдіретті Құдай\nСенсің маған түнекте жарық сыйлаған.\nМахаббатыңды жаныма менің сездірген,\nҚызмет етемін шын жүрекпен тек Саған.",
