    storage_path: null,
    duration_seconds: 409,
    lyrics:
      "Кел, Құдайға тағзым етуге,\nКел, қасына, көкке жетуге.\nКел, мойынсұнып Оған сен,\nКел, бақыт таппайсың бұған тең.\nКел!\n\nКел, мадақ айтып Исаға,\nКел, жүрегіңді Оған арна,\nКел, бүгін табын Исаға,\nКел, жалғыз Құдай - Иса Мәсіх.\nКел!\n\n\"Құдайым\"- деп мойындайды халық,\nТағы да келесің анық,\nСенгендер жұмаққа барады\nҰлы сый алады.\nУақыт келер, бәрі Сені көрер,\nБарлық халық Сені таныр,\nАл қазір Сені тыңдағандар,\nШын бақытты болар,\nКел!",
