    lyrics:
      "Дәл қазір ортамыздасың\nСиынамын, сиынамын.\nСен бізді өзгертіп жатсың,\nСиынамын, сиынамын.\n\nУәдеңе сай өмірді бердің,\nТүнекті жарып Нұр болып келдің,\nИә, Ол Сенсің - Құдайым.\n\nТолтыршы әрбір жүректі,\nСиынамын, сиынамын.\nЕмдеші әрбір жүректі,\nСиынамын, сиынамын.\nСөйлеші әрбір жүрекке,\nСиынамын, сиынамын.\nӨзгертші өмірімізді,\nСиынамын, сиынамын.\n\nКөрмесемде Сен ғажап жасайсың,\nСезбесемде Сен ғажап жасайсың.\nЖалғасады істерің Құдайым,\nЖалғасады істерің Құдайым.",
