    storage_path: null,
    duration_seconds: 198,
    lyrics:
      "Иса, кереметсің Сен!\nИса, кереметсің Сен!\nСүйгенім менің Өзіңсің!\nБір Өзіңе өмірімді арнаймын, О, Иса!\nИса, кереметсің Сен!\n\nИса сені сүйем мен, Иса сені сүйем мен\nЕсіміңді әнге салып, мадақтаймын тек Өзіңді жан Әкем\nИса сені сүйем мен\n\nИса құн төледің Сен\nБеріп азаттық айқышта, күнәдан сен мәңгілікке ақтадың\nИса құн төледің Сен",
