    audio_url: "https://repo.worshipleaderapp.com/mp3/4%20Men%20K_u_dai%20u_ly.mp3",
    storage_path: null,
    duration_seconds: 329,
    lyrics:
      "Кіммін мен,\nшақыратындай Ұлы Патша!\nЖоғалдым, тапты мені Ол\nМахаббатымен,\nМахаббатымен.\n\nАзаттық берді\nИса мәңгілік.\nМен Құдай ұлы!\nДәл солай!\n\nҚұн төлеп азаттық берді\nРақымымен.\nКүнәға құл болдым. Иса\nМен үшін өлді.-2\n\nАзаттық берді\nИса мәңгілік.\nМен Құдай ұлы!\nДәл солай!\nӘкем үйінде\nОрын бар маған.\nМен Құдай ұлы!\nДәл солай!\n\nМен таңдалдым,\nТасталмадым,\nБілем Сенде мен кіммін!\nСен жақтаушым,\nСен қолдаушым,\nБілем Сенде мен кіммін!",
    play_count: 0,
