    permission_note: "worshipleaderapp.com (#6043)",
    audio_url: "https://repo.worshipleaderapp.com/mp3/T_n_irim%20menin_%20K_u_daiym.mp3",
    storage_path: null,
    duration_seconds: 129,
    lyrics:
      "Тәңірім менің Құдайым!\nӨзіңе арнап жыр жазамын.\nБізге жіберген Ұлыңды, Құтқарушым деп,\nТәңір Ием деп қарсы аламын.\n\nЕй, халықтар, барлық ұлттар келіңдер!\nҚұдайдың махаббатын көріңдер.\nОл бізді сүйіп, Ол бізді сүйіп.\nҚұрбан ғып берді жалғыз Ұлын.\n\nИсаға сенген әркімге\nМәңгілік өмір беріледі.\nСенімін Оған жүктесе,\nЖұмақтан орын, жұмақтан орын алады.",
