    audio_url: "https://repo.worshipleaderapp.com/mp3/Omir%20berer.mp3",
    storage_path: null,
    duration_seconds: 252,
    lyrics:
      "Құдайдың тірі өзені,\nМахаббатқа бөлейді,\nТағының астынан аққан су\nТазалап бізді емдейді\n\nӨзен аққан жерлердің,\nӨзгертеді бәрінде.\nҚұдайдың берген өмірі мәңгі,\nОсында өзені болып ағады.\n\nӨмір берер суыңнан Тәңірім\nШөлімді басып ішкім келеді\nӨмір өзенде бірге жүзіп\nҚұшағыңда тынығамын\nӨмір суының Иесі\nЖаратушым менің!",
