    audio_url: "https://repo.worshipleaderapp.com/mp3/1%20Senemin%20Sag_an.mp3",
    storage_path: null,
    duration_seconds: 214,
    lyrics:
      "Әрбір арманымды беремін\nАлдына әкеп Сенің тағыңның.\nӨмірімде шалыс бассам да,\nӨзгермейді махаббатың Сенің.\nКүрескім келді өмірім үшін\nҚалжырап қалдым кетті бар күшім.\nМықты Жауынгер Жеңімпаз Патшам\nЖеңіске жетем менің Жақтаушым.\n\nТауларды қозғалтпасаң,\nҚалағанымдай мен.\nТеңізді Сен ашпасаң,\nАлдымда долданған.\nЕгер жауап қатпасаң,\nЖалбарынғанда мен,\nСенемін, сенемін, сенемін Саған.\n\nЕртеңгі күн әкелер нені?\nБәрін білесің, белгілі бәрі.\nМенің өмірім, демімсің менің,\nЖолыңмен жүрем Сенің әр күні.\n\nТыныштығым мен күшім,\nСүйенішімсің Сен.\nСен менің негізімсің\nБерік жартасымсың.\nҒажап жолдарың Сенің\nБәрінен жоғары.\nБүкіл әлем қолыңда\nБәрінің Иесі.",
