    storage_path: null,
    duration_seconds: 118,
    lyrics:
      "Адамдарды Жаратушымен\nТілдескеннен артық.\nНе жұбаныш, не қуаныш\nБіз мүлде таппадық.\n\nҚұдаймен мәңгі тілдескен тамаша,\nҚұдаймен тілдескен сондай тамаша.\n\nТәңірмен тілдессең сен,\nҰлы Ұстазбен мәңгі,\nТолық біліп аласың,\nҚұдай берген пәнді.\n\nТілдессең сен Тәңірмен\n«Әкем» деп қана,\nҚұшағында Әкенің,\nТабасың сен пана.",
