    storage_path: null,
    duration_seconds: 165,
    lyrics:
      "Құдайға жақындап, күнәдан құтылдым,\nШын жүректен сенемін Исаға.\nЖанымды тазартып, тыныштық берді Ол,\nМен Құдай Ұлына сенемін.\n\nСенемін, сенемін,\nШын жүректен сенемін Исаға.\nСенемін, сенемін,\nМен Құдай Ұлына сенемін.\n\nҚұтқарды мені Ол, сенімім ақталды,\nШын жүректен сенемін Исаға.\nШынайы Сүюші, жанымды Сақтаушы.\nМен Құдай Ұлына сенемін.\n\nСүйеніп жүремін, жақындап мен Оған,\nЖан-дүниеммен Исаға сендім.\nМәңгіге даңқтаймын, Исаға табынам,\nМен Құдай Ұлына сенемін.",
