    storage_path: null,
    duration_seconds: 257,
    lyrics:
      "Тәңірім, рақымыңды енді,\nҚалай айтпай тұра алам.\nІздеп таптың Өзің Ием, мені,\nЖүрген едім жолмен бұралаң.\n\nЖетелеші мені, өтінемін Сенен,\nӨзіңмен бірге болсам деп ем.\nҚолыңды бер маған, жетегіңе ерем,\nҚұдіретіңе анық сенем.\n\nТәңірді біреу аңыз дейді,\nҚиналса жаны іздейді.\nМен үшін Мәсіх - Құтқарушы,\nКүтеді, үмітін үзбейді.\n\nҚұтқарушым, жарылқашы Өзің,\nНәр берсін жүрекке Сөзің.\nҚарасам айқышқа үздіксіз,\nЕшқашан сарқылмас төзім.",
