    duration_seconds: 344,
    lyrics:
      "Ей, өмірім-ай! сен бізді ойландырдың,\nТіршілік келеді әлі аттырып таңдарыңды.\nКүн кештік ойланумен, күн кештік толғанумен.\nҚұдай жоқ дегендердің барлығы,\nЖүрсіңдер алданумен.\nБір кезде сұрақ туар, артында түннің күн бар?\nИесіз зат бола ма дүниеде, кезі келсе соны ұғар.\n\nЕй, өмірім-ай, сен бізді аяладың,\nТағдырдың сан жолында сен бізді аямадың.\nБіз Сенің бір қойыңбыз адасып жұртта қалған.\nСалқын жер тоңдырып жүр біздерді,\nТапсаңшы, О, Жасаған!\n\nЕй, адамзат-ай, сен өткір дана едің,\nҒасырлар бойы өзің ойыңды шыңдап келдің,\nСен неге жүрегіңнен Құдайды итересің?\nАл ертең жанға жай таппай қалсаң,\nҚұдайды сонда іздерсің.\n\nАу, досым қуана бер Құдайға келгеніңе,\nБіз мәңгі борыштамыз, сол Ұлы Иемізге.\nСаған мен не арнадым жұмбақ толы өмірімнен?\nБолашақ рухымның келбетін көремін бір Өзіңнен.",
