    duration_seconds: 267,
    lyrics:
      "Мадақтаймын Сені,\nАрдақтаймын Сені.\nӘнге қосып жырлаймын!\nӘке деймін Сені,\nДәріптеймін Сені.\nӘр сөзіңді Сенің тыңдаймын!\n\nО, Иса,\nО, Иса,\nО, Иса мәңгілік Сен жаса!\n\nСағынамын Сені,\nСүйемін тек Сені,\nТәңірім деп Сені санаймын!\nПанам деймін Сені,\nҚұрметтеймін Сені,\nАллелуя Саған айтамын!",
