    lyrics:
      "Құтқардың Сен адамзатты күнәдан\nСыйладың Сен ғажап өмір жаңадан.\nҚуанамын әрқашан мен Өзіңе\nСенің әрбір кереметтей Сөзіңе.\n\nЖүрегімде ойымда Сен болшы\nЖүрегімді Киелі Сөзіңе толтыршы.\nСүйемін мен Өзіңді Құдай Әке,\nО, Иса, Құдайсың Сен жалғыз, Көкте.\n\nБілдім мен Исадан нағыз шындықты\nАйтайын Саған барлық алғысымды\nӨзгерттің Сен менің өмірімді\nКөрсеттің Сен шындық өмір сүруді.",
