    storage_path: null,
    duration_seconds: 244,
    lyrics:
      "Әрбір тынысымсың, қалқандай Қорғаушым\nКиелі Рухың бойымда менің\nКүнделікті наным, әр күндегі нәрім\nКиелі Сөзің айтылған маған\n\nАл мен мұқтажбын Саған Ием\nАлмен Сенсіз адасқан жанмын\n\nӘрбір тынысымсың, қалқандай Қорғаушым\nКиелі Рухың бойымда менің\nКүнделікті наным, әр күндегі нәрім\nКиелі Сөзің айтылған маған\n\nАл мен мұқтажбын Саған Ием\nАл мен боламын мәңгі Сенімен",
