    storage_path: null,
    duration_seconds: 143,
    lyrics:
      "Иса Сен біздің арамыздасың,\nБізді Рухың жетелейді.\nКүнәларымызды жойдың Сен,\nСенің тағың аспанда.\n\nТәңірім, Сен-Тәңірсің бұл әлемге,\nТәңірім, Сен\nЖан-тәніммен табынамын,\nМен Саған.\n\nҚұтқарып Сен бізді күнәлардан,\nМәңгілік өмір бердің.\nҚорықпаймын мен енді өлімнен,\nДаңқтаймын Иса Тәңірді.\n\nБұл дүниенің жарығысың Сен,\nКім Саған ерем десе.\nҚараңғыда ол енді жүрмейді,\nЖарығыңа болады ие.",
