    audio_url: "https://repo.worshipleaderapp.com/mp3/22%2022%20O.mp3",
    storage_path: null,
    duration_seconds: 175,
    lyrics:
      "Абайлап қарашы менің көздерім,\nАбайлап қарашы менің көздерім,\nТәңір саған қарап тұр,\nАспаннан бәрін көріп!\nАбайлап қарашы менің көздерім!\n\nАбайлап менің тілім сөйлеші!\nАбайлап менің тілім сөйлеші!\nИса сені есітіп тұр,\nСаған сұрақ қойып тұр,\nЕшкімді сен ренжітпеп пе едің?\n\nҚұлағым неге бұл сөзге құмарсың?\nҚұлағым неге бұл сөзге құмарсың?\nҚұдай көктен есітіп тұр,\nСаған сұрақ қойып тұр,\nҚұлағым неге бұл сөзге құмарсың?\n\nАсықпай абайлап басшы аяғың!\nАсықпай абайлап басшы аяғың!\nТәңір бәрін көріп тұр,\nКүнәдан тезірек қайт,\nИса сені Өзіне шақырып тұр!\n\nАбай бол жүрегім кімге сенесің?!\nАбай бол жүрегім кімге сенесің?!\nЖүрегіңді көріп тұр, сенесің бе, сен Оған?!\nАбай бол жүрегім кімге сенесің?!",
