    lyrics:
      "Әрдайым қуаныңдар,\nТағы да қуаныңдар.\nЕш нәрсені уайымдамай\nТәңірді мадақтаңдар.\n\nҚуаныңдар, қуаныңдар!\nТағы да қуаныңдар!\nҚуаныңдар, қуаныңдар!\nИемізге қуаныңдар.\n\nӨздеріңе сонда Құдай\nТыныштық сыйлайды.\nАқыл менен ойларыңды\nИса Мәсіхте сақтайды.",
