    duration_seconds: 286,
    lyrics:
      "Иса барлық күнәмді Сен ақтап алдың.\nКиелі қаныңмен жуып тазарттың.\nТәңірім Өзіңсің өміріме келдің,\nКөктегі Әкеммен мені таныстырдың.\n\nӘкетайым менің\nШын жүрегімнің түкпірінен\nСенің алдыңа келіп басымды ием.\nӘкетайым менің\nБар әлемнің алтынынан қымбат\nСенің Киелі Рухың\nТәңірімсің Сен.\nСүйемін Сені\nСүйемін Сені",
