    storage_path: null,
    duration_seconds: 295,
    lyrics:
      "Жаратқан бар әлемді Құдай Ием,\nМейірімді, кең пейілді жан Ием.\nБір Өзіңсің мәңгілікке жетелер,\nБір Өзіңсің Құтқарушым, Қорғаушым.\n\nТуған елім, туған жерім, қазағым,\nҚанша қасірет, қаншама көп азабың.\nКөзіңді ашып, жан-жағыңа қарашы,\nЖалған өмір жетегінде жүрсің сен.\n\nБауырластар, абзал достар, туысқандар,\nҚұдай Ұлы Иса Мәсіхті қабылдаңдар.\nБойыңдағы бар күнәңді мойындап,\nТәубеге кеп, бір Құдайға сиыныңдар.\n\nШын жүректен сенім артсаң Құдайға,\nКенелерсің қуанышқа, бақытқа.\nИса Тәңір шексіз сүйеді бәріңізді,\nҮлкен-кіші, жасыменен кәріңізді.",
