    duration_seconds: 138,
    lyrics:
      "Өмірімді Саған арнадым,\nБір Өзіңе ұмтыламын.\nСенімімді жасырмадым,\nБір Өзіңе сиынамын.\n\nТек Сенің мәңгілік адалдығың,\nБолсын деп өмірлік қорғанышым.\nКүндіз-түні Саған қараймын,\nЕң Ұлы менің Құдайым.\n\nСалшы мені Өз жолыңа,\nҚараңғыда адаспайын.\nАлшы мені Өз қолыңа,\nСаған келіп паналайын.",
