    storage_path: null,
    duration_seconds: 283,
    lyrics:
      "Сенімен келеді тілдескім,\nНағыз жақын жан Досым менің.\nЖоғарыдан Сен маған қарап,\nДүрсілін естисің жүректің.\n\nСенімен тілдескім келеді,\nЖеңілдетіп қайғы-мұңымды.\nБұл өмір мені түсінбейді,\nАшамын Саған бар сырымды.\n\nТілдескім келеді Сенімен,\nөйткені алыста достарым.\nҚайғымды бөліспей олармен,\nбәрін де Саған мен беремін!\n\nАйналамды түнек басқанда,\nТілдесуді күтем асыға.\nЖоғарыдан Сен маған қара,\nСенімді Досым, кел қасыма.",
