    storage_path: null,
    duration_seconds: 271,
    lyrics:
      "Ең - жоғары, ең - ұлы!\nТабиғаттан және барлық адамнан (бүкіл ғаламнан)!\nДаналықтан, барлық амалдан!\nӘуел бастан барсың бар болғансың!\n\nПатшалықтардан, тақтардан,\nТаңырқанатын, бар ғажайыптардан!\nБар байлық пен інжу-маржаннан!\nЕшкім тең келмес ең ұлысың!\n\nШегеленді, қабірде жатты!\nӨлу үшін, өмірге келді!\nСолған гүлдей, тапталған мені,\nЖаны ашып, көтерді,\nЕң - ұлы!",
