    is_unknown_author: true,
    permission_note: "worshipleaderapp.com (#5834)",
    audio_url: "https://repo.worshipleaderapp.com/mp3/Bu_l%20_lemnin_%20bastamasy%20Ozin_%20%20dombyra%20varianty.mp3",
    storage_path: null,
    duration_seconds: 276,
    lyrics:
      "Бұл әлемнің бастамасы Өзің болып,\nӘлемнің Ақыры да Сен боласың.\nАспаннан жердегіге қуат беріп,\nАл Өзің кең әлемге құпиясың.\n\nО,Тәңір, бұл әлемнің Патшасы.\nО, Тәңір, бұл әлемнің Қолдаушысы.\nИіліп Саған ғана тағзым етем.\nО, Тәңір, өмірімнің берекесі.\n\nКешір мені, күнәлардан арылайын,\nИса Тәңір Өзіңе мен табынайын.\nҚуаныштан, жұбаныштан көздің жасы\nТөгіледі, Құтқарушым, айналайын.\n\nӨзің бол мендегі шынайы сенім,\nМәңгілік жүрегімде жаса менің.\nЖаратқан, көрсет енді шындық жолын.\nЖарық көріп Саған келсін қазақ елім.",
