    storage_path: null,
    duration_seconds: 202,
    lyrics:
      "Киелі Тәңір, ұмтылам Саған\nЖан тыныштығы Сенде, білемін.\n\nКеудеңде Сенің табамын тыным,\nБасылады жүрегім менің\n\nБілемін Сенде мәңгі қуаныш\nЖәне баянды махаббат.\n\nЕшкім мені енді айыра алмайды,\nБұл мәңгілік қуаныштан.\n\nКелгенде менің ақырғы демім,\nҚабылдарсың мені, сенемін.",
