    storage_path: null,
    duration_seconds: 248,
    lyrics:
      "Ием Саған қол созамын мен\nКеудемді шаттық кернейді\nКүш аламын жалғыз Өзіңнен,\nАлақанымда сермейді\n\nКиелі қолы Исаның,\nСақтады мені күнәдан,\nАшып жұмақ есігін,\nҚұтқарды мені, тозақтан!",
