    storage_path: null,
    duration_seconds: 107,
    lyrics:
      "Өмірдің қиын шағында,\nЖүректі мұң басса,\nБір ғажайып дұғаны мен,\nҚайталаймын жатқа.\n\nСол сөздің үндестігінде,\nҚұдіретті күш бар,\nҚасиетті бір көркемдік,\nСол сөздерден шығар.\n\nЖүректің жүгі жеңілдеп,\nЖаным рахат табар.\nЖан-дүниеме түскен жарық,\nҮміт отын жағар.\n\nАуырлық жүректен түседі,\nкүмән да алыстайды.\nЖылаймын да, сенемін де,\nжаным рахат табады!",
