    duration_seconds: 218,
    lyrics:
      "Арайымен атқан күннің нұр күліп,\nЖан-жүрегім ақтарылды жаңғырып.\nБұлақ көзін ағып жатқан таптым мен,\nҚуанышым таусылмайды мәңгілік.\n\nҮміт, мақсат алға мені жетелер,\nЕш солмайтын мәңгілік сый әперер.\nЖарығың боп мына өмірде жүруге,\nТәңір Ием, Өзің қуат бере гөр.\n\nАйтпай-ақ та жүрегімді білесің,\nМұқтажымның ең асылын, киесін.\nОятсаңшы қазағымды, елімді,\nҚұтқарылсын, қисық жолын түзесін.\n\nШапағатың бүкіл елге тарасын,\nШаттық әнім шарлап қазақ даласын.\nБасымды иіп сұраймын мен, Тәңірім!\nҚұтқарсаңшы барлық қазақ баласын.",
    play_count: 0,
    uploaded_by: 'developer',
