    storage_path: null,
    duration_seconds: 135,
    lyrics:
      "Мадақтаймын Сені\nАрдақтаймын Сені\nӘнге қосып Сені жырлаймын.\nӘке деймін Сені\nДәріптеймін Сені\nӘр Сөзіңді Сенің тыңдаймын\n\nО, Иса, О, Иса,\nО, Иса Мәңгілік Сен жаса!\n\nСағынамын Сені\nСүйемін деп Сені\nТәңірім деп Сені санаймын\nПанам деймін Сені\nҚұрметтеймін Сені\nАллелуя Саған айтамын",
