    storage_path: null,
    duration_seconds: 176,
    lyrics:
      "Сиынуды үйретші Тәңірім,\nКиелі заңыңды сақтайын.\nТәкаппар жүрегімді өзгертші,\nИманды болайын әрдайым.\n\nОрын ал мәңгілік жүрегімнен,\nКиелі Рухыңмен басқарып.\nМадақтайын Сені жан-дүниеммен,\nӨсиеттеріңді орындап.\n\nТазарып киелі Қаныңменен,\nЖүрегімді таза сақтайын.\nШынайы сүйейін жақынымды,\nКиелі атыңды даңқтайын.",
