    storage_path: null,
    duration_seconds: 179,
    lyrics:
      "Мадақта жаным Құдайды,\nӘн саламын Оған!\nМадақта жаным Құдайды,\nИгі Оған ән салған!\n\nҚұдайға даңқ, Жаратқанға\nҚұдайға даңқ, Аллелуя!\n\nҚұдай Ұлы және күшті,\nОның құдіреті\nҚұдай Ұлы және шексіз\nАқыл парасаты\n\nКішіпейілді қолдайды,\nҚиналғанда күш беріп.\nАдалды көріп тұрады,\nМұқтаждықтарын беріп.\n\nКім Құдайға сенім артса,\nҰятқа қалмайды.\nӘн айтшы Құтқарушыға,\nАдам Оған ән айтшы.",
