    audio_url: "https://repo.worshipleaderapp.com/mp3/Abukhair%2007.mp3",
    storage_path: null,
    duration_seconds: 306,
    lyrics:
      "Түнгі дала тұрды тұнжырап,\nТұрды жарық жұлдыз жарқырап.\nГетсиман бағында бір адам\nТұрды көздеріне жас алып.\n\n«О, Әкем егер қаласаң\nБолсыншы Сенің қалауың.»\nОсы еді айтқан сөздері\nЖай ғана тұрған Адамның.\n\nКенеттен сәулесі нұр шашып,\nЖақыннан періште көрінді.\nПеріште үнсіз бір сыр ашып\nЖаңағы Адамға күш берді.\n\nҚолдарына қару ұстаған,\nБір топ әскер келді әр жақтан.\nСол Адамды ешбір жазықсыз\nСоқпағына салды жан жақтан.\n\nТөменге қарап тұрдың Сен,\nБолсаң да таза бір мінсіз.\nМойныңа алдын күнәсін\nЖай ғана басқа адамның",
