    storage_path: null,
    duration_seconds: 199,
    lyrics:
      "Мұңға батсам жүрегім мұздап,\nОл қасымда бір бола ма?\nКүйбің тірлігі бастан асса да,\nҚұшақ жайып қарсы ала ма?\n\nМәсіх бізбен мәңгі бірге!\nОл мықты, берік ірге!.\n\nАлдым соқпақ артым болса,\nОл қасымда бір бола ма?\nСөніп жарық күн, қараңғы болса,\nНұр бере ме кең далама?\n\nСапар шексем қайтып келмеске,\nОл қасымда бір бола ма?\nБеріп сый-тарту, құрмет көрсетіп,\nМәңгі досым болып қала ма?",
