    storage_path: null,
    duration_seconds: 176,
    lyrics:
      "Адасып жүргенде азап шегіп,\nСен мені іздедің, Құтқарушым.\nАлдамшы өмірге қызығумен\nӨзіңнен адасып жүріппін мен.\n\nКеремет мынау бір табиғатың,\nАй менен жұлдызды жарқыраттың,\nАспан мен жерді де Сен жараттың,\nБарлығы Өзіңе бағынатын.\n\nМың алғыс айтамын Өзіңе мен,\nКөкірегімді ояттың Рухыңменен.\nКөзімді аштың Сен, жұмулы еді,\nЖүрегім тас еді, жібіттің сен.\n\nТәңірім, Өзіңе бас иемін,\nҚұдіретті күшіңе мен сенемін.\nО, неткен күнәкар жан едім мен,\nАйқышта азаппен Сені өлтірген.\n\nСен мені сүйесің, иланам ғой,\nЖаныңды мен үшін қинадың ғой.\nӨзіңе келгенді кешіріп Сен,\nМәңгілік өмірді сыйладың ғой.\n\nБар бақыт Өзіңсің өмірдегі,\nКүнәмді жуасың көңілдегі.\nТек қана Өзіңе бас иемін,\nТәңірім, кешірші, кешір мені.",
    play_count: 0,
    uploaded_by: 'developer',
    status: 'published',
    is_active: true,
