    storage_path: null,
    duration_seconds: 226,
    lyrics:
      "Далама көз салсам, өткенді ойға алсам,\nҚаншама күнәм бар, сан жетпес санасам.\n\nЖүректе маза жоқ,\nӨмірде қайғым көп.\nТыныштық таппайды,\nЖүрегім жылайды.\n\nЯ, Тәңір Жаратқан, бар әлемді құлпыртқан,\nБар әлемнің Иесі, құтқаршы азаптан.\n\nТәңірім естіді, күнәмды кешірді.\nКүнәкар мен үшін Өз Ұлын жіберді.\n\nО, қандай қуаныш!\nО, қандай жұбаныш!\nТыныштық табылды,\nЖүрегім қуанды!\n\nКүнәдан құтқарған, біз үшін қиналған.\nСенемін Исаға, Ол келген Құдайдан.",
