    storage_path: null,
    duration_seconds: 308,
    lyrics:
      "Жүр еді қасарысып жүрегім,\nАлыс кетіп мен Сенен, мейірімді жүзіңнен!\nСонда Сен құшағыңды ашып кең,\nШақырдың Өзің мені зор мейіріміңмен!\nАлдыңа келемін Ием,\nКешірім сенен өтінем.\nЖан сырымды ақтарам Саған,\nТек қана Саған.\n\nҚалауым қарсы болып еркіңе,\nАдасты алыста берік болмай сертіне.\nКелемін қалжыраған күйімде,\nСенемін Тәңірім қабылдайсың үйіңе.\nҚабылдап Әке Өзіңе,\nҚуантты мені мәңгіге.\nМадақтап Ұлы Есіміңді мен,\nАрнадым әнімді.\n\nСенімің әлсіресе сенің де,\nҚысылма қайтадан Иемізге келуге.\nСебебі сені Ол шын сүйеді,\nТәңірім, кешіріп рақымына бөлейді\nЕсімі мәңгі киелі,\nМадақта Тәңір Иені.\nСарқылмайды мәңгілікке,\nОның мейірімі.",
