    storage_path: null,
    duration_seconds: 257,
    lyrics:
      "Кетпеші, Иса, менен кетпеші,\nСенсіз мен қорқам өмір жолында,\nОрманда жүрген жолаушыдай жалғыз,\nСен менің қасымда әрқашан болшы.\n\nБала кезден теріс жолменен жүрдім,\nТек Сен ғана мені сақтадың.\nЖамандығы көп Тәңірім дүниенің,\nКеңесің керек, мені қалдырма.\n\nТас жүрек адам сүюді білмес,\nШын бақыттылық - өзгені сүю,\nҚұдайсыз өмірдің мәні болмас,\nСүюші Ием мені қалдырма.\n\nМәңгілік көктемді кездестірсем мен,\nСенімен Иса Тәңірім өлсем де.\nҚабірден оят Елазар сияқты,\nӨлімнен өткіз мәңгі өмірге.",
