    storage_path: null,
    duration_seconds: 207,
    lyrics:
      "Жүзген кемедей өмір білінбей,\nЗымырап өте шығар,\nНе күтер алда, толқын бар жолда,\nКейде құзға ұрар.\nСен де, мен де, біз мүлде білмейміз,\nТек Құдай ғана білер,\nУақыт та келер біз көкті көрер,\nБар арман орындалар.\n\nО, қайда сол жұмақ төрі,\nТек сонда болғым келеді,\nЖарық мәңгі сөнбес жерде,\nӨлім, қайғы болмас елде.\nО, қайда сол жұмақ төрі,\nДостарымның болар бәрі,\nТоқталмас бала күлкісі, шаттық үні.\n\nЖаз да өтеді, қыс та жетеді,\nУағымен, көп күттірмей,\nЖастық тұрмайды, жылдар ұрлайды,\nҚарттық келер білдірмей.\nКүш біткен кезде, үміт жоқ өзге,\nТек көкке көз тігерміз.\nАрман боп келген, үмітпен сенген,\nЖарық жұлдыз көреміз.",
