    storage_path: null,
    duration_seconds: 212,
    lyrics:
      "Қанша қиындықтар\nӨмірімізде өтіп жатқанда,\nҚуанышсыз күндер\nАдам қайғырудан шаршағанда,\nҚұдайым, сұраймын,\nЖұбаныш әкелші жаныма,\nӘкелші, әкелші жаныма, әкелші жаныма.\n\nАсығып жүргенде,\nТіршілік арасында кеткенде,\nКөңілім толмайды, Сенсіз істеген әр ісіме.\nӨзіңнен сұраймын,\nСенімімді сақташы жаныма,\nСақташы, сақташы жаныма, сақташы жаныма.\n\nӘлсіздік келгенде,\nУайым күндері маған жеткенде,\nМені тастамайсың,\nСенемін Сенің колдауыңа.\nЖалғыз қалғанымда,\nСөйлейсің жүректен жаныма,\nЖүректен, жүректен жаныма, жүректен жаныма.\n\nТыныштық іздеймін,\nАспанда нәзік түн жамылғанда,\nСұлу ай жарқырап,\nЖұлдыздар төгіліп жанғанда.\nСонда мен сеземін,\nБір Өзің керексің жаныма,\nКерексің, керексің жаныма, керексің жаныма.",
