      "Марал мөлдір суды қалай аңсаса,\nМенің жаным да,\nСені іздеп шөліркейді, Тәңір,\nСені аңсайды.\n\nҚұдайым, Сен қорғанышым,\nБар үмітім менің, жігерім, күшім,\nЖанымды да, өмірімді де,\nӨзіңе тек арнадым.\n\nКүндіз-түні рақым жасаған,\nТәңірімді жырлаймын.\nӨмір берген Құдай Әкеме,\nДұғамды бағыштаймын.\n\nБағушым, ең жақын Досым,\nЖетелейді күшті қолың.\nМейірімді Тәңір Иемді,\nӘніммен мадақтаймын.",
