    storage_path: null,
    duration_seconds: 216,
    lyrics:
      "Қорға, Тәңірім, мені, қорға, Тәңірім,\nҚорға мені мына дүниеден.\nҚолымда кітабың киелі Сөзіңмен,\nҚорға, Тәңірім, мені, қорға, Тәңірім!\n\nДаналық бер маған, киелі Сөз,\nЖүрекке сүйіспеншілік, Мәсіх Рухын.\nМәңгілікке жетелеші мені Өзің,\nҚорға, Тәңірім, мені, қорға, Тәңірім!\n\nҚай жерде жүрсем де, Сөздеріңді,\nХалыққа естіртем, Мәсіх ісін.\nСол кезде дұшпандар ізіме түскенде,\nҚорға, Тәңірім, мені, қорға, Тәңірім!\n\nКүнәлі өмірге қызықсам мен,\nСен маған қуат бер алданбауға.\nҚасиетті сенімде тұрақты болуға,\nЖетеле, Тәңірім, қорға, Тәңірім!",
