    duration_seconds: 432,
    lyrics:
      "Сен мені суға шақырасың\nӨте алмаймын сен болмасаң\nСенімім мұхитта орнайды\nСонда көремін, Ием, сені\n\nШақырам сені атыңмен\nТолқыннан көзімді көтерем\nДауыл болса, Менің жаным тыныш табады\nМен сендемін, Сен мендесің\n\nТерең суда мейірімділігің\nСенің қолың жетелейді\nҚорқыныш қоршап сәтсіздік пе\nТастамадың, тастамайсың\n\nРухына Құдайдың шексіз мен сенемін\nСу үстімен жетелеші, мені шақырған жеріңе\nМен жеңе алмайтын тереңдікке жеткіз\nСенімім менің қуатты қасымда",
