    duration_seconds: 374,
    lyrics:
      "Тіршіліктің қайнар көзі,\nЖаратқан Иеміз!\nЖер бетіне келді Өзі!\nБіз Оған сенеміз!\nБіз Оған сенеміз!\n\nЖалындаған махаббатын\nЖүрекпен сеземіз\nТөкті әлемге шапағатын\nБіз Оған сенеміз!\n\nЖаратушым жетелейді\nАлып алақанымен\nЖауымнан қауіп төнбейді\nЖанында бірге жүрсем\nҚамалымсын таудай биік\nҚалың тастан қаланған\nДұшпан келсе жолын қиып\nҚорғанышым бола алған!\n\nИса, ол - Иса!",
