    storage_path: null,
    duration_seconds: 295,
    lyrics:
      "Менің жүрегім, аңсап жылағанда,\nБар қайғы қасіретті, Саған бергім келеді.\nТәңірім тек Сені, жүрегім іздейді,\nҚысылып шығатын есік таппай дүрсілдейді!\n\nТәңірім,осы кезде Сен ғана,\nМаған жақынсың, Ием!\nМені, құшағыңа тартып, қысасың Сен!\nӨзіңе, жақындаттың мені,\nЖұбатасың Сен, Өз қолыңда, мені сәбидей!\n\nОсыны түсінбей, Сенен алыстап,\nҚұшағыңнан, сытылып, шыққым келеді!\nАлайда Тәңірім, осы уақытта,\nСенің, Рухыңа толып, рахаттамын мен!",
