    storage_path: null,
    duration_seconds: 222,
    lyrics:
      "Ұшамын көктегі ғарышқа,\nСамғаймын алысқа, алысқа.\nСені көремін, Саған еремін.\nШексіз қуанар сонда жүрегім.\nЖаныма қуаныш сыйлайсың.\nТаңымды жалғайсың, жалғайсың.\nЖаратқан Ием, Саған сенемін.\nҚайда жүрсем де, болдың тірегім.\n\nЖетеле, жетеле арманға,\nЖас қанатым менің талғанда.\nЖалғыз Сен бөлейтін бақытқа.\nАлғыс айтып әнді салғанда.\n\nМақтаймын Өзіңді әлемге,\nЖасашы мәңгіге, мәңгіге.\nӨмірдің сырын, махаббат жырын\nБарлық халыққа бірдей ұсындың.\nЖүздерің жарқырап жайнаған.\nНұрланшы әрқашан, әрқашан.\nЖарығың барда жүрейін алға,\nТоқтап қалмайын қараңғы жолда.",
