    storage_path: null,
    duration_seconds: 157,
    lyrics:
      "О Құдай Ием\nӨзіңе мен басымды ием\nСен біздің көктегі Әкемізсің\nӘрқашан Атыңды мадақтаймын\nСебебі Сен бұлттардан жоғарысың\nӨмірдің мәнісің\nЖүректің әнісің\nСені сүйемін!\n\nО, Құдай Тәңірім,\nРақмет Саған Ұлың үшін.\nОл бізді күнәдан құтқарды.\nО, Иса, біз Саған ерушіміз.\nСебебі Сен -\nҚұдай Әкеден келгенсің,\nБіз үшін өлгенсің,\nМәңгі өмір бергенсің,\nСені сүйеміз.\n\nО, Құдай Әке,\nӨзіңе мен қайтсем жетем.\nӨйткені Сен бізге Рухың бердің.\nО, Киелі Рух,\nБастай гөр мәңгі өмірге.\nСебебі Сен -\nЖанымның қорғаушысы,\nСенім қолдаушысың,\nБақыт жолдаушысың,\nСені сүйеміз!",
