    lyrics:
      "Қанатыңның астында алаңсыз,\nТыныштықта боламын, Тәңір.\nСол жерден сізде қорған табасыз,\nМейіріміне кенелер өмір.\n\nҚанатының, Қанатының, Қанатының астында.\n\nҚанатыңның астына тығылам,\nМенің берік баспанам Өзіңсің.\nКеш түсіндім білмедім бұрыннан,\nШексіз Сенің сүйіспеншілігің.\n\nАлаңсыз өмір сүргің келе ме?\nИсаның соңынан сен қалмай ер.\nТағдырыңды қолына бергін де,\nОның қанатының астына кел.",
