      "Иса өзгертші мені, Кемшілігім көп себебі.\nҚұрметтеймін тек Сені, Сендей болғым келеді.\n\nО, Иса, о, Иса,\nСендей болғым келеді.\n\nЕнді менің жүрегім, Саған ғана сенеді.\nСенсің жалғыз тірегім, Сендей болғым келеді.\n\nҮмітім бар өшпейтін, Әлі-ақ лаулап жанамын.\nСенімім бар өлмейтін, Сендей түбі боламын.",
