    storage_path: null,
    duration_seconds: 232,
    lyrics:
      "Тауға көзді қадаймын\nҚайдан жәрдем келер деп\nКөк пен жерді жаратқан\nТәңір Ие маған жар\n\nТайдырмайды табаныңды Ол\nҰйықтамайды Қорғаушы\nИсраилды Қолдаушы\nҰйықтамайды, қалғымайды\n\nТәңір Ие қорғайды,\nҚұдіретімен қолының.\nКүндіз күннің тимесін деп,\nТүнде айдың сәулесі.\n\nЖамандықтың бәрінен\nИеміз сені қорғайды.\nЖаныңды Ол сақтайды,\nЖаныңды Ол қорғайды.\n\nМәңгі-бақи бүгіннен\nИеміз сені қорғайды.\nКету-келу сапарыңды\nТәңір Өзі қолдайды.",
