    audio_url: "https://repo.worshipleaderapp.com/mp3/22_Zhyr.mp3",
    storage_path: null,
    duration_seconds: 348,
    lyrics:
      "Тәңірім менің Бағушым\nМен еш нәрседен тарықпаймын\nОл мені жасыл жайлауға жайып\nТұнық суға апарады\n\nЖаныма күш береді\nЕсімі қасиетті болғандықтан\nМен Оған нық сенемін\nОл мені тура жолмен жүргізеді\n\nҚараңғы шатқалда жүрсем де\nҚауіп-қатерден қорықпаймын.\nСебебі Сен қасымдасың,\nАқ таяғың сүйенішім.\n\nСен маған дастархан жаясың,\nДұшпандарымның көз алдында.\nҚұрметтеп мені қарсы алып,\nТостағанымды толтырасың.\n\nЖақсылық пен мейірімділік\nӨмірлік менің үлесім.\nМен мәңгі Тәңірдің үйінде\nҚала беретін боламын",
