    storage_path: null,
    duration_seconds: 234,
    lyrics:
      "Бәрі де жақсы болады,\nӘрдайым Сен қасымда ,\nИса - Тәңірім!\nМен сенемін Сен жетелейсің мені!\n\nНұрсың Сен өмірімде,\nЕң жақын жүрегіме,\nБақытсыздықтан бізді сақтайсын,\nӘркезде бізбен бірге!\n\nБәрі де жақсы болады,\nӘрдайым Сен қасымда ,\nИса - Тәңірім!\nМен сенемін Сен жетелейсің мені!\n\nМенің атым мәңгі - Өмір Кітабында,\nЖазылды мен сенемін!\nБүкіл әлем шайқалса да,\nИса Тәңір - менің тірегім!",
