    lyrics:
      "Иса біздің берік панамыз,\nТек Исадан бақыт табамыз.\nТек Исамен бірге боламыз,\nТар жолменен өтіп барамыз.\n\nКездесейік енді аспанда,\nКездесейік Тәңір алдында.\nКездесейік жұмақ төріңде,\nИе болып мәңгі өмірге.\n\nТек Исада болсын ойыңыз,\nТек Исаның сөзін тыңдаңыз.\nАбайлаңыз, құлап қалмаңыз,\nТар жолменен өтіп барамыз.\n\nКел, шырқайық бүгін бәріміз,\nИса болсын біздің әніміз.\nЖарасып тұр бүгін сәніміз,\nБіз Исамен мәңгі біргеміз.",
