    duration_seconds: 246,
    lyrics:
      "Аспанда таңғы жұлдыз туған кезде,\nНұрынан жердің жүзі арайланды\nШығыста данышпандар атқа қонып,\nКөз тігіп, кең дүние қарай қалды.\n\nО, ғажап, дүниеге сәби келді.\nО, ғажап, бұл әлемге өмір келді.\nИіліп, данышпандар тағзым етіп\nАлдыңда нәрестенің сәлем берді.\n\nҚуаныш жер жүзіне таратылды,\nБетлехем шахарында бала туды.\nДәуіттің ұрпағынан Исраилде,\nКелді, - деп, Құтқарушым, - дала тұрды.\n\nТаңданды бүкіл әлем қайран қалып,\nӘндетті періштелер сайран салып.\nЕркексіз таза қыздан туған сәби,\nТүбінде жай ғана адам болмас анық.",
