    storage_path: null,
    duration_seconds: 210,
    lyrics:
      "Ұмытпаймын мен, бізді құтқарғаныңды,\nТеңізді жарып Мысырдан алып шықтың Сен.\n\nҚұтқардың, суларды ұстап тұрдың Тәңір Ием\nО, Яхве!\n\nКүреседі мен үшін, Оның күшімен жеңем\nАллелуйя, аллелуйя!\nТеңіздерді жарды Ием, тұңғиыққа жетелеп.\nАллелуйя, аллелуйя!\n\nКүдіз бұлт боп алдымызда жүресің,\nОт болып түнде Өзің қорғайсың Ием!\n\nМені іздеп келдің Сен,\nҚолымнан алдың Ием!\nУәделі жерге мені апардың Тәңірім!\nІстеріңді ұмытпаймын,\nМадақтаймын Сені\nМахаббатың өлімнің күшін жеңіп шықты!",
