    storage_path: null,
    duration_seconds: 205,
    lyrics:
      "Қайғы тартып қиналғанда,\nО, Құдай, Саған келем.\nӘлсіз болып, күш кеткенде,\nҚұшағыңа енем.\n\nО, Құдай Саған келемін\nРухымды қайта тірілт.\nМейіріммен қуат беріп,\nТас жүрегімді жібіт.\n\nАзапты өмір сүріп келдім,\nҚайдан тыныштық табамын?\nСаған келдім, Құтқарушым.\nҚасыңда мәңгі қаламын.\n\nЖаным кейіп, налып тұрмын,\nӨмір солай өте ме?\nЕңсем түсіп, шаршап тұрмын,\nӨзің мені жетеле.",
