    storage_path: null,
    duration_seconds: 207,
    lyrics:
      "Тамаша, Өзіңмен бірге болған.\nБіз Сені бірігіп даңқтаймыз.\nТамаша қиыншылыққа шыдасаң,\nҮмітпен мақсатқа жетеміз.\n\nТамаша, жүрегің таза болса .\nТамаша жамандық болмаса.\nТамаша жан тыныштығын алсақ.\nТамаша, Құдаймен табысқан.\n\nТамаша, жаның мен өміріңді\nМәсіхке сеніп сен тапсырсаң.\nТамаша, азғындықты тойтарып,\nзұлымдыққа қарсы тұра алсақ.\n\nТамаша, Исамен барлық жерде.\nОнымен өміріміз жеңіл .\nТамаша, Исаға жүректі ашсақ.\nТәңір Ием бізді қолдайды.\n\nТамаша, Құдайдың қол астында.\nТастамайды Ол бізді ешқашан.\nТар жол, тайғақ кешумен жүргенде,\nқорғайды Иеміз әрқашан.",
