    storage_path: null,
    duration_seconds: 201,
    lyrics:
      "Көк аспан күтеді мені\nҚуаныштың болмай шегі\nКездесем Тәңірім Исамен\nКиелі Рухпен, Әкеммен.\n\nГүл тәжі, әрине гүл тәжі\nБеретін сыйлығы Әкемнің.\nГүл тәжі, әрине гүл тәжі\nБеретін сыйлығы Әкемнің./\nАллелуя! Аллелуя!\n\nБұл жұмақтың қаласы шашбауын\nАйнала періште толған гүл.\nЖарқырап жүздері достардың\nИсаның келуін күтіп тұр.\n\nКездесем Петірмен, Жоханмен\nжәне көп киелі бауырмен.\nҚұшақтайд(ы) мені олар жақын кеп,\nҚуаныш таусылмайд(ы) тасып кең.",
