    storage_path: null,
    duration_seconds: 166,
    lyrics:
      "Менің жүрегімде Иса сөйлеп тұрсын.\nОйымда, сезімімде Ол жасасын.\nБұл жалғанда мені Иса іздеп тапқанда,\nСонда ғана, сонда ғана жүрек тынышталмақ.\n\nЖеңісті маған Иса Өзі алып берді.\nҰлы күшін жүрегіме Ол табыс етті.\nҰлы күшін Иса маған сыйлағанда,\nЖүрегіме тыныштық майын төккізді!\n\nЖаным күресіп, әлсізденіп мен тұрсам да,\nИса Өзі маған Рухын жіберді.\nКөңілімнің баспанасын мен сонда таптым,\nЖүрегіме шаттық, қайрат Ол алып берді!",
    play_count: 0,
    uploaded_by: 'developer',
    status: 'published',
