    artist: "Белгісіз автор",
    is_unknown_author: true,
    permission_note: "worshipleaderapp.com (#6646)",
    audio_url: "https://repo.worshipleaderapp.com/mp3/11%20Zhan%20zhag_yma.mp3",
    storage_path: null,
    duration_seconds: 347,
    lyrics:
      "Жан-жағыма қарадым, қайдан көмек келер деп,\nТәңірім маған қашан, бостандық берер деп.\nЖан-жағыма қарадым, қайдан көмек келер деп,\nТәңірім маған қашан, бостандық берер деп.\n\nТәңірім, Ол мені естіді, қаққандай болды есікті,\nӨмірімді, Тәңіріме күмәнсіз толық арнаймын Оған,\nЖалғыз арман, жалғыз өмір, тек сол, қалған!\n\nТәңірім мені жұбатты, сәбиіндей қуантты,\nАуырып тұрған жаныма, аямай берді қуатты.\nқуанышым да Өзіңсін, Жұбанышым да Өзіңсің,\nСенсіз жаным жаралы, Сенсіз күнім қараңғы!",
