    storage_path: null,
    duration_seconds: 178,
    lyrics:
      "Құдай сүйіп біздерді жалғыз Ұлын жіберді\nМәңгіліктің есігі, айқара ашық, кір енді.\n\nЖаңа өмірде жаңаша,\nҚуанайық балаша.\nТатулассаң Тәңірмен,\nӨмір сонда тамаша!\n\nИса келіп өмірге, жаңа дәуір басталды.\nПеріштелер әнімен, күңірентті аспанды.\n\nӨмір босқа өтпесін, қаулап гүлдер көктесін.\nИса жаққан шамшырақ, ешқашанда өшпесін.",
