    storage_path: null,
    duration_seconds: 286,
    lyrics:
      "Бәрі жақсы болып көрінді,\nБәрі жақсы болып сезілді.\nӨткізген мынау күндерім,\nНе жақсылық әкелді?\n\nБіреулер іздейді байлықты\nБайлықтан іздейді бақытты.\nМынау жалған дүниеде\nІздеумен өтер уақытты.\n\nЕң жақсысы өмірдің\nҚұдайға ғана бағыну.\nМойынсұнып әрқашан\nШын жүректен табыну.\n\nКөзімізді ашайық,\nАяқты нық басайық.\nҚұдай Сөзімен сергек боп\nИсаның келуін тосайық.\n\nМәңгілік қамқор Құдайың\nБір өзіңе жар екен.\nБұдан асқан тыныштық\nБақытты өмір бар ма екен?",
