    audio_url: "https://repo.worshipleaderapp.com/mp3/05%20O.mp3",
    storage_path: null,
    duration_seconds: 114,
    lyrics:
      "Жедел хабар келеді,\nКеледі келеді!\nНе болып қалды, не болып қалды?\nБетлехем қаласында,\nҚаласында, қаласында,\nТуды Иса - Мәсіх!\nТуды Иса - Мәсіх!\n\nОған орын болмады,\nБолмады, болмады,\nАдам үйінде, адам үйінде,\nКедейлікте туылды,\nТуылды,туылды,\nАқырда жатты,\nАқырда жатты!\n\nБақташылар сол түні,\nсол түні, сол түні,\nҚуанды шексіз, Қуанды шексіз,\nПеріштелер жариялап,\nжариялап, жариялап,\nҚуанды шексіз,\nҚуанды шексіз.\n\nКөкте Құдай даңқталсын,\nДаңқталсын, даңқталсын,\nБерген Ұлы үшін! Берген Ұлы үшін!\nЖер жүзінде тыныштық,\nТыныштық, тыныштық,\nБолсын мәңгілік,\nБолсын мәңгілік.",
