    storage_path: null,
    duration_seconds: 311,
    lyrics:
      "Құтқаруға қазақ елін, Тәңір Иса келді!\nШексіз рақымын көрсетіп, мейірімін берді.\nМәңгі мекен алтын қала, баратын жеріміз,\nАқ жолыңды көрсет Ием, Саған біз келеміз!\n\nАңсаймыз Сені! Аңсаймыз Сені!\nТәңірім келші, Иса!\n\nАқ батаң қонсын жеріме, ояну келсін еліме!\nҚазақстан Сенің жүзіңді іздесін,\nХалқым Сені мадақтасын!",
