    storage_path: null,
    duration_seconds: 143,
    lyrics:
      "Тербетеді әуен менің жанымды,\nТыңдай ма екен Тәңір менің әнімді?\nҚайта-қайта келді жүрекке осы ән.\nМадақтасам деп ем Иса Тәңірді.\n\nЖүрегімде орнап Сенің сөздерің,\nАшылды ғой Ием, менің көздерім.\nАқ жолыңа түстім, баста Сен мені.\nАйтқанына ермен енді өзгенің.\n\nАқиқатты нұсқа, ашып ұлыңа,\nОяныш бер менің алыс қырыма.\nМадақтайын Сені, Иса Тәңірім.\nАқ батаңды берші осы жырыма.\n\nКөкте Сенің даңқың арта берсінші,\nБарлық халқым келіп Саған ерсінші.\nАшшы Өзің жүрегін қазақ елімнің,\nАдамзатқа даңқың қайта келсінші.\n\nМадақтаңдар, достар, Тәңірді бүгін,\nМадақтаңдар осы ұлылығы үшін.\nАспанменен жерде мадақтаңдаршы,\nИеміздің рақым, шапағаты үшін.",
    play_count: 0,
    uploaded_by: 'developer',
    status: 'published',
    is_active: true,
    created_at: "2026-11-18T00:00:00.000Z",
