    storage_path: null,
    duration_seconds: 315,
    lyrics:
      "Тәңірім Сенің Рухыңды аңсаймын.\nКүтемін Сені Киелі күтемін.\nСүйіспеншілігіңмен, жүрегімді толтыршы.\nАлдыңа келіп, жүзіңді іздеймін.\n\nӘкетайым Өз құшағыңа алшы.\nӨз Жүзіңменен мені өзгертші.\nСенің алдыңа Тәңірім аңсап,\nМен жүгіріп шығам(ын)\nТәңірім құшағыңа қысып мені алшы.\n\nИса  Сені сүйемін.\nИса Сені сүйемін\nИса  Сені сүйемін.\nТәңірім құшағыңа қысып мені алшы! 2р.",
