    storage_path: null,
    duration_seconds: 229,
    lyrics:
      "Тек қана Құдайда тыныштық табасың.\nСоңынан ерсең сен Тәңірдің, тек Соның.\nШақырып Өзіңе Ол сені,\nБақытты еткісі келеді.\nКелсеңші, келсеңші!\n\nТаста бұл күнәкар өмірді, зұлымды,\nСүйіспеншілігі жоқ осы жалғанды.\nАсық сен келуге Исаға.\nБақыт пен тыныштық табасың Исада!\n\nШақырады Тәңірім енді асық сен.\nАйқышта Қаны ақты Оның сен үшін.\nНеге енді асықпай тұрсың,\nҚұдай қауымына кел, досым келсеңші!\n\nСақтайды сені жамандықтан, азаптан.\nӘкеңдей бәріне де ортақ әрқашан.\nӘлсіресең Ол күш береді.\nЕгер де сиынсаң сен Оған әр күні!",
