    storage_path: null,
    duration_seconds: 170,
    lyrics:
      "Қуанам Құдайымды тапқаныма,\nАрайлап сол бір таңның атқанына.\nЖүректің лүпілдеген жалынымен\nПаш етіп ақиқатты жатқаныма.\n\nСен менің, Иса Тәңір, Құтқарушым!\nМендей боп барлық халқым құтқарылсын.\nҚабыл ал, ей, адамзат ақиқатты,\nСенің де Иса Тәңір Құтқарушың.\n\nТапсыр да тағдырыңды Құдайыңа,\nӘрқашан сиынып жүр ұдайы да.\nҚадам бас мәңгі өмірге, ақиқатқа,\nБелшеңнен бата берме уайымға.\n\nМәңгілік, Ол мәңгілік - Иса жолы.\nБұрын күн түсінбеппіз біздер оны.\nКүнәнді кешіреді Ол қайырылсаң,\nСол Иса сен үшін де құрбан болды.\n\n«Танысын, міне, осыны» деп туыпты.\nСенен Ол тілемейді көп білікті.\nАқиқат - Иса жолы - Құдай жолы.\nБауырым, соны білсең жеткілікті.",
