    storage_path: null,
    duration_seconds: 330,
    lyrics:
      "Қараңғы түнде тыныштық енгенде\nСен ұйықтамайсың анам менің!\nЕстимін ерніңнің жәй ғана сыбырын,\nАтымды қайталап сиынасың.\n\nЕгер қасымда сен болмағаныңда,\nТөзер ме едім қиындыққа.\nАнам сен мені Құдайға жолдадың,\nҚұдай қауымына жетеледің.\n\nӨмірден қалған бетіңдегі іздер\nБалалық шақтан таныс маған.\nЖайсыз мінезіммен тыңдамай сені мен,\nЖүрегің жаралы, жыладың сен.\n\nМенің қайғымнан ағарды шаштарың,\nБілемін оған себепші мен.\nКешір, анашым, кешірші анашым,\nКөп қайғы тартқыздым, кешір мені.\n\nБар аналардың балаға арнаған,\nДұғасын Тәңірім қабыл алсын.\nМәңгілік орында аналар да көрсін,\nӨз ұлдары мен қыздарын да.",
