    storage_path: null,
    duration_seconds: 254,
    lyrics:
      "Мәсіхтің сүйіспеншілігі,\nКеремет өзендей, шексіз ұлы,\nТолқынындай болады теңіздің,\nТаза, терең, байтақ және тұнық.\n\nЕгер Мәсіх сезімінен,\nЖұрдай болсақ үмітсізбіз.\nҚалар едік сүйе алмай,\nҚұтқарушыдай адамды біз.\n\nКелсеңші тез, тезірек келсеңші,\nОның күтіп тұрғанын білсеңші.\nЕсігіңді қағып тұр, ашсаңшы,\nӨзіңе тегін қабылдасаңшы.\n\nМәсіхсіз бәрі де қирар еді,\nДәл сол сәтте тыныс тоқтар еді.\nМәсіхті танып білгенде егер,\nӨмірің мүлде өзгерер еді.\n\nСені сүйді, мені де Ол сүйді,\nӨзіне сенбегенді де сүйді.\nКелші Оған, Ол әлі күтеді,\nМәсіхсіз өмір бекер өтеді.",
