    audio_url: "https://repo.worshipleaderapp.com/mp3/05%20K_u_daidyn_%20Sozimen%20omirim%20ozgerdiArman_%2005.mp3",
    storage_path: null,
    duration_seconds: 269,
    lyrics:
      "Құдайдың Сөзімен өмірім өзгерді\nҚуанды жүрегім.\nТатулық, жақсылық күтіп тұр алдымда\nМен Оған сенемін.\n\nИса,Иса, менің Тәңірім\nИса,Иса, жақын Жан Досым.\n\nӨлімнен құтқарып бір жолды мәңгілік\nӨмірді сыйлады.\nОсылай Тәңірім біз үшін айқышта\nАзаппен қиналды.\n\nКүнәкар әлемнен бас тартып қазағым\nБір жола келіңдер\nҚұдайдың ұсынған Құрбандық Тоқтысы\nИсаға сеніңдер.\n\nАдамзат келсін деп, шындықты білсін деп\nҚауымын орнатты.\nСенгендер қуаныш, бақытқа кенеліп,\nҚайғысын ұмытты.",
