    lyrics:
      "Махаббатың ғажап Сенің,\nРақымды Құдайым!\nТолығымен құн төледің,\nЛайықсыз болсам да!\n\nҚұдай сондай жақсы,\nҚұдай сондай жақсы,\nҚұдай сондай жақсы,\nОл сондай жақсы!\n\nӨмір бойы қарап өтем,\nСенің Атың\nКүнәкарды құтқардың,\nӨлімді жеңдің!\n\nЖарылқашы Құдай!",
