    storage_path: null,
    duration_seconds: 233,
    lyrics:
      "Бұл қойылым емес\nИем, шын жүректі\nҒибадат деп тілеймін\nСезімге батуға\nМен мүлдем ұмтылмаймын\nМен тек сен үшін айтамын\n\nОо Ән айтамын мен\nШын жүрекпен айтсам тек\nТек саған менің Ием\nБілмеймін неге\nЖасадым жасанды оны\nОл Сенің даңқың үшін\n(Ооо Ооо)\n\nКемелдіктің орнына\nЖүрегімді қаладың\nБар нәрсемді беремін\nБір сәтке созылатын әннен де\nАдалдыққа толы өмір сүремін\nӘнім тек мақсатпен шырқала берсін -\nАқыр соңында, Бар даңққа лайықсың",
