    storage_path: null,
    duration_seconds: 334,
    lyrics:
      "Құтқардың мені, әсім әніңмен қоршадың мені Ием!\nАзат еттің Сен жаулардан мені, бар қорқыныш кетті.\n\nКүнәнің құлы емеспін.\nҚұдайдың баласымын!\n\nТуылмай тұрып таңдадың мені, сүйіп есім бердің,\nҚайта туылдым, отбасым болып, төгілген қаныңмен.\n\nҚұшағыңа алып Көктегі Әкенің\nҚоршайды мені ұраны азаттықтың,\nҚұтқарылдық біз күнәнің құлдығынан.\nҰлы мен қызымыз бостандық жариялаймын!\nО-о-о-о...\n\nМенің күшім теңіздерді аштың Сен,\nМахаббат жойды қорқынышты.\nҚұтқардың енді жар саламын,\nҚұдайдың баласымын!",
