    lyrics:
      "Таңдап откен әуелі бастан,\nКүналармен ажыратып тастап\nСен таңдаған жұлдыз мен едім о-о-ой!\nСаған куә болады аспан!\n\nЖасама күнә ей халқым,\nЖақындап қара Құдайға!\nСөздеріме құлақ сал,\nҚұдай сөзін айтамын!\n\nЖақын барып жаныңа халқым,\nҚұдай сөзін жеткізейін,\nТыңда менің сөзімді халқым, о-о-ой!\nАзаттығымды білдірейін!\n\nТыңда, тыңда, тыңдаңыздар,\nҚұдай сөзін айтайын ұйқас\nӨлеңменен айтайын достар, о-о-ой!\nҚүтқарушы болады Иса!",
