    duration_seconds: 204,
    lyrics:
      "Бұралаң тар жолмен аттанып барамын,\nЖеңісті, мәңгі өмір сүремін.\nЖүрегім жай тапты, жарқырап жанарым,\nСебебі мен Құдайға сенемін!\n\nЖақсы мен жаманды айыра білемін,\nЖаныма не керегін сеземін.\nНеліктен жаралдым, оны да білемін,\nСебебі мен Құдайға сенемін!\n\nАлысып шындықпен, күресіп күнә тұр,\nЗұлым рух жайлады жалғанды.\nАл мені шақырып жұмақта мұра тұр,\nСебебі мен Құдайға сенемін!\n\nКелсе де қайғы-мұң, ысырып тастаймын,\nАртамын жүгімді Тәңірге.\nӨзімді сүйетін Құдай бар, саспаймын,\nЖеткізер Ол мәңгілік өмірге!\n\nЗұлымдық жеңіліп, жүрегім қуанды,\nӘкеге барар жолмен келемін.\nЖүрегім жайланып, жаным да уанды,\nСебебі мен Құдайға сенемін!",
