      "Айқыш ағаштағы Құрбандық арқылы,\nАйқара ашылды, Көктің қақпалары\nСенімен жүздессем қасыңа барамын,\nКенеліп Әкенің күшіне!\n\nАйқыш ағаштағы Құрбандық арқылы,\nАйқара ашылды, Көктің қақпалары\nСенімен жүздессем қасыңа барамын,\nКенеліп Әкенің даңқына!\n\nИса Патшалығын бізге ашты,\nПатшалық өз құшағын бізге жайды!\n\nТек құшағыңда махаббатқа толам,\nӘке құшағында Исаны мен көрем!\nСенімен жүздессем қасыңа барамын,\nКенеліп Әкенің даңқына!",
