    storage_path: null,
    duration_seconds: 191,
    lyrics:
      "Тұнық аспан жымың қағады сан жұлдыздар\nКөз ілеспей ағып барады шоқ жұлдыз да\nЖұлдыз ақса арман тілектер орындалар\nДеп сенгендер жұлдызға тілек жолдап жатар\n\nАл менің тілегім Саған жетеді\nЖұлдыздан да жылдам\nҚалауымды Тәңірім ескересің\nЖолдаған Саған\n\nТұнық аспан Айдың сәулесі нұр төгеді\nТілегіме құлақ түргенің сезіледі\nЖарық айдың нұры астына қайта-қайта\nТәңіріме тілек айтуға мен келемін\n\nАл менің тілегім Саған жетеді\nЖұлдыздан да жылдам\nҚалауымды Тәңірім ескересің\nЖолдаған Саған",
