    duration_seconds: 239,
    lyrics:
      "Жұлдыздар жарқырап жанғанда,\nЖарық ай көрініп аспанда,\nТәңірім, Өзіңе жүректі ашқанда,\nТәңірім, Сен мені құтқардың.\n\nӨмірдің таба алмай бақытын,\nЖолымның біле алмай бағытын,\nТұншығып тұңғиық түбінде қалғанда,\nТәңірім, Сен мені құтқардың.\n\nКүнәнің шыға алмай торынан,\nАдасып жүріппін жолымнан.\nЖүректі тағы да жалғыздық басқанда,\nТәңірім, Сен мені құтқардың.\n\nӨмірдің қайғы мен азабын,\nҰмыттым күнәнің мазағын.\nТәңірім құтқарды, қуаныш сыйлады,\nТәңірім, күнәдан құтқарды.",
